function ptToPx(pt) { return (pt * PX_PER_IN) / PT_PER_IN; }
/** px → pt. */
function pxToPt(px) { return (px * PT_PER_IN) / PX_PER_IN; }
/** mm → px. */
function mmToPx(mm) { return (mm * PX_PER_IN) / MM_PER_IN; }
/** px → mm. */
function pxToMm(px) { return (px * MM_PER_IN) / PX_PER_IN; }

