      const raw = await fetchJson(`${BASE}/${file}`);
      items = (raw || []).map(d => ({ id: d.id, name: d.name || d.id, box: d.box || null }));
      designs.set(collection, { loaded: true, items, raw: new Map((raw || []).map(d => [d.id, d])), registered: new Set() });
      return items;
